// RE:MK Local LZString Backup Compression Bridge
window.LZString = window.LZString || {
  compressToEncodedURIComponent: function(str) {
    if (!str) return "";
    try { return encodeURIComponent(btoa(unescape(encodeURIComponent(str)))); } catch (e) { return ""; }
  },
  decompressFromEncodedURIComponent: function(compressed) {
    if (!compressed) return null;
    try { return decodeURIComponent(escape(atob(decodeURIComponent(compressed)))); } catch (e) { return null; }
  }
};
